// CONFIDENCE: MEDIUM - add/remove and recursion semantics read in full; return flag LOW. Original 0x1423aec80.
// Owner list: HiddenPrimitiveComponents (APlayerController, +0x2f8). Weak-pointer equality and creation are engine helpers.
bool bChanged = false;
if (SceneComp)
{
    if (SceneComp->IsA(UPrimitiveComponent::StaticClass()))
    {
        const FWeakObjectPtr WeakComp(SceneComp);
        if (!bNewHidden)
        {
            // Remove every entry equal to WeakComp (order of the rest is kept).
            const int32 OldNum = HiddenPrimitiveComponents.Num();
            HiddenPrimitiveComponents.RemoveAll([&](const FWeakObjectPtr& Entry) { return Entry == WeakComp; });
            bChanged = HiddenPrimitiveComponents.Num() != OldNum;
        }
        else if (!HiddenPrimitiveComponents.Contains(WeakComp))
        {
            HiddenPrimitiveComponents.Add(WeakComp);
            bChanged = true;
        }
    }
    if (bPropagateToChildren)
    {
        // Explicit stack walk over AttachChildren, same visiting order as the decompile (push children, pop from the back, recurse).
        TArray<USceneComponent*> Stack = SceneComp->AttachChildren;
        while (Stack.Num() > 0)
        {
            USceneComponent* Child = Stack.Pop();
            if (Child)
            {
                Stack.Append(Child->AttachChildren);
                NativeSetComponentHiddenForController(Child, bNewHidden, true);
            }
        }
    }
}
return bChanged;
